parameters.jsCode:
// Bestimmt fuer jede Zeile das Angebotsalter und daraus die faellige
// Nachfassstufe. Entscheidend ist der Vergleich mit der bereits erreichten
// Stufe im Sheet: ohne ihn wuerde derselbe Kunde ab Tag 3 jeden Morgen
// dieselbe Erinnerung bekommen - der sicherste Weg, einen Auftrag zu
// verlieren.
const heute = new Date();
const raus = [];

for (const eintrag of $input.all()) {
  const z = eintrag.json;
  const status = String(z['Status'] ?? '').trim().toLowerCase();

  // Nur offene Angebote. Alles andere (angenommen, abgelehnt, storniert)
  // wird stillschweigend uebersprungen statt angeschrieben.
  if (status && !['offen', 'versendet', 'verschickt'].includes(status)) continue;

  const rohdatum = String(z['Angebotsdatum'] ?? '').trim();
  if (!rohdatum) continue;

  // Sheets liefert deutsche Datumsangaben als Text. new Date('05.09.2026')
  // liest das als Mai oder gar nicht - deshalb selbst zerlegen.
  const teile = rohdatum.match(/^(\d{1,2})\.(\d{1,2})\.(\d{4})$/);
  const datum = teile
    ? new Date(Number(teile[3]), Number(teile[2]) - 1, Number(teile[1]))
    : new Date(rohdatum);
  if (Number.isNaN(datum.getTime())) continue;   // unbrauchbare Zeile lieber auslassen als raten

  const tage = Math.floor((heute - datum) / 86400000);
  const bisher = Number(z['Nachfassstufe'] ?? 0) || 0;

  let stufe = 'keine';
  let neueStufe = bisher;
  if (tage >= 21 && bisher < 3) { stufe = 'intern'; neueStufe = 3; }
  else if (tage >= 10 && bisher < 2) { stufe = 'zweite'; neueStufe = 2; }
  else if (tage >= 3 && bisher < 1) { stufe = 'erinnerung'; neueStufe = 1; }

  if (stufe === 'keine') continue;

  // Ohne Empfaengeradresse kann nur intern eskaliert werden.
  const email = String(z['E-Mail'] ?? '').trim();
  if (!email && stufe !== 'intern') { stufe = 'intern'; neueStufe = 3; }

  raus.push({
    json: {
      angebotsnummer: String(z['Angebotsnummer'] ?? '').trim(),
      kunde: String(z['Kunde'] ?? '').trim(),
      ansprechpartner: String(z['Ansprechpartner'] ?? '').trim(),
      email,
      angebotsdatum: rohdatum,
      betrag: String(z['Betrag'] ?? '').trim(),
      leistung: String(z['Leistung'] ?? '').trim(),
      tage_offen: tage,
      stufe,
      bisherige_stufe: bisher,
      neue_nachfassstufe: neueStufe,
      heute: heute.toLocaleDateString('de-DE')
    }
  });
}

return raus;

